import pandas as pd
x=pd.read_parquet('results/infer/inference_test_xgb.parquet')
def run(d,thr):
 rows=[]
 for _,g in d.groupby('event_id'):
  used=set()
  for r in g[g.score_xgb>=thr].sort_values('score_xgb',ascending=False).itertuples():
   ss={r.i,r.j,r.k}
   if not used&ss: rows.append(r);used|=ss
   if len(used)>=6:break
 o=pd.DataFrame(rows)
 return o.is_truth.sum()/d.is_truth.sum(),o.is_truth.sum(),len(o)
for t in [0,.02,.05,.1,.115,.2,.3,.5]: print(t,run(x,t),flush=True)
